from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from django_otp.plugins.otp_static.models import StaticDevice, StaticToken

class BackupTokenManagementViewSet(viewsets.ViewSet):
    permission_classes = [permissions.IsAuthenticated]

    @action(detail=True, methods=['get'])
    def backup_codes(self, request, pk=None):
        # Constrain device lookup to the authenticated user
        try:
            device = StaticDevice.objects.get(pk=pk, user=request.user)
        except StaticDevice.DoesNotExist:
            return Response({"error": "Device not found"}, status=status.HTTP_404_NOT_FOUND)

        tokens = StaticToken.objects.filter(device=device).values_list('token', flat=True)
        return Response({"device": device.name, "backup_tokens": list(tokens)})
